select '00000000-0000-4000-b000-000000000001', 'ayuda-con-el-movil-y-la-tablet-con-paciencia-d001', '00000000-0000-4000-a000-000000000002', 'offer', 'Ayuda con el móvil y la tablet, con paciencia', 'Te explico paso a paso cómo usar WhatsApp, hacer videollamadas, guardar fotos o instalar aplicaciones. Voy a tu casa o quedamos en una cafetería. Nunca te pediré contraseñas: las escribes tú.', c.id, s.id, m.id, 'at_home', 1500, 'hourly', false, array['whatsapp', 'videollamadas', 'mayores']::text[], 'published', 'approved', now() - interval '2 days 0 minutes', now() - interval '2 days' + interval '30 days', now() - interval '2 days 0 minutes'
