select '00000000-0000-4000-b000-000000000002', 'recoger-un-certificado-en-la-oficina-del-distrito-d002', '00000000-0000-4000-a000-000000000001', 'request', 'Recoger un certificado en la oficina del distrito', 'Necesito que alguien recoja un certificado de empadronamiento que ya he solicitado. Te daré una autorización firmada el día del recado. Oficina del distrito de Gràcia, por la mañana.', c.id, s.id, m.id, 'in_person', 2000, 'fixed', true, array['empadronamiento', 'autorización']::text[], 'published', 'approved', now() - interval '1 days 1 minutes', now() - interval '1 days' + interval '30 days', now() - interval '1 days 1 minutes'
