select '00000000-0000-4000-b000-000000000005', 'puesta-a-punto-de-ordenadores-lentos-d005', '00000000-0000-4000-a000-000000000008', 'offer', 'Puesta a punto de ordenadores lentos', 'Reviso por qué va lento tu ordenador, elimino programas que sobran, actualizo el sistema y hago una copia de seguridad de tus fotos y documentos. Puedo hacerlo en remoto o en tu casa en Madrid centro.', c.id, s.id, m.id, 'hybrid', 1800, 'hourly', false, array['windows', 'mac', 'copia de seguridad']::text[], 'published', 'approved', now() - interval '4 days 4 minutes', now() - interval '4 days' + interval '30 days', now() - interval '4 days 4 minutes'
