select '00000000-0000-4000-b000-000000000006', 'paseos-de-perros-de-una-hora-por-russafa-d006', '00000000-0000-4000-a000-000000000009', 'offer', 'Paseos de perros de una hora por Russafa', 'Paseos de una hora para perros de cualquier tamaño. Recojo y devuelvo al perro en casa, llevo bolsas y agua, y te escribo por el chat al terminar. Máximo dos perros a la vez para dedicarles atención.', c.id, s.id, m.id, 'in_person', 1000, 'fixed', false, array['perros', 'paseos']::text[], 'published', 'approved', now() - interval '2 days 5 minutes', now() - interval '2 days' + interval '30 days', now() - interval '2 days 5 minutes'
