select '00000000-0000-4000-b000-000000000019', 'clases-de-guitarra-para-principiantes-d019', '00000000-0000-4000-a000-000000000022', 'offer', 'Clases de guitarra para principiantes', 'Aprende tus primeras canciones en pocas semanas. Clases de una hora en mi casa o en la tuya, para adolescentes y adultos. Si no tienes guitarra te presto una las primeras clases.', c.id, s.id, m.id, 'in_person', 1400, 'hourly', false, array['guitarra', 'música']::text[], 'published', 'approved', now() - interval '11 days 18 minutes', now() - interval '11 days' + interval '30 days', now() - interval '11 days 18 minutes'
