select '00000000-0000-4000-b000-000000000020', 'llevar-un-sofa-de-dos-plazas-a-un-piso-nuevo-d020', '00000000-0000-4000-a000-000000000023', 'request', 'Llevar un sofá de dos plazas a un piso nuevo', 'Tengo que trasladar un sofá de dos plazas y una mesa desde La Florida hasta el centro. Hay ascensor en origen; en destino es un segundo sin ascensor. Necesito furgoneta y ayuda para subirlo.', c.id, s.id, m.id, 'in_person', 4000, 'fixed', true, array['sofá', 'furgoneta']::text[], 'published', 'approved', now() - interval '1 days 19 minutes', now() - interval '1 days' + interval '30 days', now() - interval '1 days 19 minutes'
