select '00000000-0000-4000-b000-000000000021', 'transports-petits-per-lleida-i-comarca-d021', '00000000-0000-4000-a000-000000000024', 'offer', 'Transports petits per Lleida i comarca', 'Recullo mobles comprats de segona mà, electrodomèstics o caixes i els porto on calgui. Furgoneta gran i ajuda per carregar. Demana pressupost amb l’origen i la destinació.', c.id, s.id, m.id, 'in_person', null, 'quote', false, array['furgoneta', 'transport']::text[], 'published', 'approved', now() - interval '5 days 20 minutes', now() - interval '5 days' + interval '30 days', now() - interval '5 days 20 minutes'
